const body = $input.first().json.body ?? $input.first().json;

const token = $input.first().json.headers?.['x-webhook-token']
           ?? $input.first().json.headers?.['X-Webhook-Token']
           ?? '';
const expectedToken = $env.WEBHOOK_TOKEN ?? '';
if (expectedToken && token !== expectedToken) {
  throw new Error('Token inválido — acesso não autorizado');
}

if (!body.nome || !body.whatsapp) {
  throw new Error('Campos obrigatórios ausentes: nome, whatsapp');
}

const whatsappRaw = String(body.whatsapp).replace(/\D/g, '');

return [{ json: {
  nome:               body.nome ?? '',
  whatsapp:           whatsappRaw,
  email:              body.email ?? '',
  classificacao:      body.classificacao ?? 'NAO_QUALIFICADO',
  score:              body.score ?? 0,
  segmento:           body.segmento ?? '',
  fase:               body.fase ?? '',
  faturamento:        body.faturamento ?? '',
  dor:                body.dor ?? '',
  aquisicao:          body.aquisicao ?? '',
  orcamento:          body.orcamento ?? '',
  prazo:              body.prazo ?? '',
  experiencia:        body.experiencia ?? '',
  texto_livre:        body.texto_livre ?? '',
  utm_source:         body.utm_source ?? '',
  utm_medium:         body.utm_medium ?? '',
  utm_campaign:       body.utm_campaign ?? '',
  disqualifier_reason: body.disqualifier_reason ?? '',
  recebido_em:        body.data ?? new Date().toISOString(),
} }];

const lead      = $('Validar e Normalizar Payload').first().json;
const resultado = $input.first().json;

const existing = Array.isArray(resultado) ? resultado[0] : null;

// Se já existe, encerra o fluxo silenciosamente
if (existing) {
  console.log(`Lead Frio duplicado ignorado: ${lead.nome} (${lead.whatsapp}) — já existe como ${existing.id}`);
  return [];
}

return [{ json: lead }];

const result = $input.first().json;
const lead   = $('Validar e Normalizar Payload').first().json;

const inserted = Array.isArray(result) ? result[0] : result;
const leadId   = inserted?.id ?? null;

if (!leadId) {
  console.error('Falha ao inserir lead:', JSON.stringify(result));
} else {
  console.log(`Lead Frio inserido: ${leadId} — ${lead.nome} (score ${lead.score})`);
}

return [{ json: { success: !!leadId, lead_id: leadId } }];
